CREATE TABLE `professional_work_schedules` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`professional_id` BIGINT UNSIGNED NOT NULL,`unit_id` BIGINT UNSIGNED NULL,`weekday` TINYINT UNSIGNED NOT NULL,`starts_at` CHAR(5) NOT NULL,`ends_at` CHAR(5) NOT NULL,`active` BOOLEAN NOT NULL DEFAULT TRUE,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `professional_work_schedules_public_id_key` (`public_id`),INDEX `pws_tenant_prof_weekday_active_idx` (`tenant_id`,`professional_id`,`weekday`,`active`),CONSTRAINT `professional_work_schedules_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `professional_work_schedules_professional_id_fkey` FOREIGN KEY (`professional_id`) REFERENCES `professionals`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `professional_work_schedules_unit_id_fkey` FOREIGN KEY (`unit_id`) REFERENCES `business_units`(`id`) ON DELETE SET NULL ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
